# shellcheck shell=bash disable=SC2154  # variables come from apply-theme.sh and the earlier parts
# scripts/theme.d/06-neovim.sh: part of apply-theme.sh, sourced in order in the same shell (not run on its own)
# ==========================================
# 6. Neovim Color Engine (nvim.lua)
# ==========================================
cat <<EOF > "$CACHE_DIR/nvim.lua"
-- Generated by apply-theme.sh
local bg          = "$BG"
local bg_alt      = "$BG_ALT"
local bg_visual   = "$BG_VISUAL"
local fg          = "$FG"
local fg_muted    = "$FG_MUTED"
local accent      = "$ACCENT"
local accent_soft = "$ACCENT_SOFT"
local ansi_red    = "$ANSI_RED"
local ansi_green  = "$ANSI_GREEN"
local ansi_yellow = "$ANSI_YELLOW"
local ansi_cyan   = "$ANSI_CYAN"
local accent_dim  = "$ACCENT_DIM"

vim.cmd("highlight clear")
vim.o.background = "dark"

-- Full base16 palette for all plugin highlight groups (LazyVim: pickers, completion, which-key,
-- statusline, treesitter, diagnostics). Skipped in a plain Neovim without mini.base16.
local ok, base16 = pcall(require, "mini.base16")
if ok then
    base16.setup({
        palette = {
            base00 = bg,          base01 = bg_alt,      base02 = bg_visual,   base03 = fg_muted,
            base04 = "$(blend_hex "$BG" "$FG" 62)", base05 = fg, base06 = "$(blend_hex "$FG" "#ffffff" 10)", base07 = "$(blend_hex "$FG" "#ffffff" 25)",
            base08 = ansi_red,    base09 = "$(blend_hex "$ANSI_RED" "$ANSI_YELLOW" 50)", base0A = ansi_yellow, base0B = ansi_green,
            base0C = ansi_cyan,   base0D = accent,      base0E = accent_soft, base0F = accent_dim,
        },
        use_cterm = false,
    })
end
vim.g.colors_name = "colorengine"

local hl = function(group, opts)
    vim.api.nvim_set_hl(0, group, opts)
end

-- Editor & UI
hl("Normal",       { fg = fg, bg = bg })
hl("NormalNC",     { fg = fg, bg = bg })
hl("NormalFloat",  { fg = fg, bg = bg_alt })
hl("FloatBorder",  { fg = accent, bg = bg_alt })
hl("CursorLine",   { bg = bg_alt })
hl("CursorLineNr", { fg = accent, bg = bg_alt, bold = true })
hl("LineNr",       { fg = fg_muted, bg = bg })
hl("SignColumn",   { fg = fg_muted, bg = bg })
hl("Visual",       { bg = bg_visual })
hl("Search",       { fg = bg, bg = accent, bold = true })
hl("IncSearch",    { fg = bg, bg = accent_soft, bold = true })
hl("StatusLine",   { fg = bg, bg = accent, bold = true })
hl("StatusLineNC", { fg = fg_muted, bg = bg_alt })
hl("WinSeparator", { fg = bg_visual, bg = bg })
hl("VertSplit",    { fg = bg_visual, bg = bg })
hl("Pmenu",        { fg = fg, bg = bg_alt })
hl("PmenuSel",     { fg = bg, bg = accent, bold = true })
hl("TabLine",      { fg = fg_muted, bg = bg_alt })
hl("TabLineSel",   { fg = bg, bg = accent, bold = true })
hl("TabLineFill",  { bg = bg })
hl("Directory",    { fg = accent, bold = true })
hl("Title",        { fg = accent, bold = true })
hl("MatchParen",   { fg = accent, bg = bg_visual, bold = true })
hl("NonText",      { fg = fg_muted })
hl("DiagnosticError", { fg = ansi_red })
hl("DiagnosticWarn",  { fg = ansi_yellow })
hl("DiagnosticInfo",  { fg = accent_soft })
hl("DiagnosticHint",  { fg = ansi_green })

-- Syntax Highlighting
hl("Comment",      { fg = fg_muted, italic = true })
hl("Constant",     { fg = accent_soft })
hl("String",       { fg = ansi_green })
hl("Character",    { fg = ansi_green })
hl("Number",       { fg = accent_soft })
hl("Boolean",      { fg = accent, bold = true })
hl("Identifier",   { fg = fg })
hl("Function",     { fg = accent, bold = true })
hl("Statement",    { fg = accent, bold = true })
hl("Conditional",  { fg = accent, bold = true })
hl("Repeat",       { fg = accent, bold = true })
hl("Operator",     { fg = accent_soft })
hl("Keyword",      { fg = accent, bold = true })
hl("PreProc",      { fg = accent_soft })
hl("Type",         { fg = ansi_yellow })
hl("Special",      { fg = accent_soft })

-- Markdown / Obsidian notes (render-markdown.nvim): every heading level its own color, as text color
-- and as a full-width bar in a dark tint of it, so ## and ### are easy to tell apart (a terminal
-- can't make headings bigger)
local headings = {
    { "$ACCENT",      "$(blend_hex "$BG" "$ACCENT" 24)" },      -- #
    { "$ANSI_CYAN",   "$(blend_hex "$BG" "$ANSI_CYAN" 18)" },   -- ##
    { "$ANSI_GREEN",  "$(blend_hex "$BG" "$ANSI_GREEN" 15)" },  -- ###
    { "$ANSI_YELLOW", "$(blend_hex "$BG" "$ANSI_YELLOW" 13)" }, -- ####
    { "$ACCENT_SOFT", "$(blend_hex "$BG" "$ACCENT_SOFT" 11)" }, -- #####
    { fg_muted,       bg_alt },                                 -- ######
}
for i, c in ipairs(headings) do
    hl("@markup.heading." .. i .. ".markdown", { fg = c[1], bold = true })
    hl("RenderMarkdownH" .. i,                  { fg = c[1], bold = true })
    hl("RenderMarkdownH" .. i .. "Bg",          { fg = c[1], bg = c[2], bold = true })
end
hl("@markup.link.label",     { fg = accent_soft, underline = true })
hl("@markup.link.url",       { fg = fg_muted, underline = true })
hl("@markup.list.checked",   { fg = ansi_green })
hl("@markup.list.unchecked", { fg = accent })
hl("RenderMarkdownCode",     { bg = bg_alt })
hl("RenderMarkdownTableHead", { fg = accent })
hl("RenderMarkdownTableRow",  { fg = fg_muted })
hl("RenderMarkdownCancelled", { fg = fg_muted, strikethrough = true }) -- [~]
hl("RenderMarkdownImportant", { fg = ansi_red, bold = true })         -- [!]
hl("RenderMarkdownForwarded", { fg = ansi_cyan })                     -- [>]
EOF

